import { MongoClient } from 'mongodb';

// Database url generated by MongoDB Atlas cloud service
const url = 'mongodb+srv://vygoj-app:VH7Be7IkT5IS0QtQ@cluster0.uieic.mongodb.net/myFirstDatabase?retryWrites=true&w=majority';

// Manages the connection with the database
class Database {
  // The client connection to the database. 
  database: MongoClient | null = null;

  // Establish the connection with the database
  // Call this function before using the database object
  async connect() {
    return this.database = await MongoClient.connect(url);
  }

  // Get a reference to the database
  get() {
    if (this.database) {
      return this.database;
    }
    throw new Error('Must call database.connect() before getting it');
  }
}

// Exports the Singleton Database instance
const database = new Database();
export default database;
